CREATE TABLE "OperationsIncident" (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('WARNING','CRITICAL')),state TEXT NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','ACKNOWLEDGED','RESOLVED')),path TEXT NOT NULL,details JSONB NOT NULL,episode INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,"firstSeenAt" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),"lastSeenAt" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),"resolvedAt" TIMESTAMPTZ(6),"acknowledgedBy" TEXT REFERENCES "User"(id),"acknowledgedAt" TIMESTAMPTZ(6));
CREATE INDEX "OperationsIncident_state_lastSeenAt_idx" ON "OperationsIncident"(state,"lastSeenAt");
CREATE TABLE "OperationsIncidentEvent" (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"incidentId" TEXT NOT NULL REFERENCES "OperationsIncident"(id),episode INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN ('OPEN','ACKNOWLEDGED','RESOLVED')),"actorId" TEXT REFERENCES "User"(id),"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),details JSONB NOT NULL);
CREATE INDEX "OperationsIncidentEvent_incidentId_createdAt_idx" ON "OperationsIncidentEvent"("incidentId","createdAt");
